<script setup lang="ts">
import { computed,onMounted,ref } from "vue";type Row=Record<string,any>;const data=ref<Row>({branding:{},institutions:[],programs:[],events:[],notices:[]}),loading=ref(true),error=ref("");const brand=computed(()=>data.value.branding||{});const school=computed(()=>brand.value.short_name||brand.value.trade_name||brand.value.legal_name||data.value.institutions?.[0]?.trade_name||"Instituição");function apply(){document.documentElement.style.setProperty("--brand-primary",brand.value.primary_color||"#006D77");document.documentElement.style.setProperty("--brand-secondary",brand.value.secondary_color||"#0D1B2A");document.documentElement.style.setProperty("--brand-accent",brand.value.accent_color||"#F59E0B");document.title=school.value;}
async function load(){try{const r=await fetch('/api/v1/public/context',{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('Portal indisponível');data.value=await r.json();apply();}catch(e){error.value=e instanceof Error?e.message:'Erro ao abrir portal';}finally{loading.value=false;}}onMounted(load);
</script>
<template><div v-if="loading" class="center">Carregando portal…</div><div v-else-if="error" class="center"><div class="panel"><h1>Portal indisponível</h1><p>{{error}}</p></div></div><div v-else class="site"><header><div class="brand"><div class="mark">◎</div><div><strong>{{school}}</strong><small>{{brand.legal_name}}</small></div></div><nav><a href="#instituicao">Instituição</a><a href="#programas">Cursos</a><a href="#eventos">Eventos</a><a href="#noticias">Comunicados</a></nav></header><main><section class="hero"><span>Educação, comunidade e informação</span><h1>{{school}}</h1><p>{{data.institutions?.[0]?.legal_name}}</p></section><section id="instituicao" class="public-grid"><article class="panel" v-for="i in data.institutions" :key="i.id"><span class="eyebrow">Instituição</span><h2>{{i.trade_name}}</h2><p>{{i.legal_name}}</p><small>{{i.education_system}}</small></article></section><section id="programas" class="section"><div class="section-title"><h2>Programas educacionais</h2></div><div class="public-grid"><article class="panel" v-for="p in data.programs" :key="p.id"><h3>{{p.name}}</h3><p>{{p.education_level}} · {{p.modality||'presencial'}}</p></article><p v-if="!data.programs?.length" class="empty">Consulte a instituição para conhecer a oferta vigente.</p></div></section><section id="eventos" class="section"><div class="section-title"><h2>Eventos</h2></div><div class="public-grid"><article class="panel" v-for="e in data.events" :key="e.id"><span class="eyebrow">{{e.event_type}}</span><h3>{{e.name}}</h3><p>{{e.location}}</p><small>{{new Date(e.starts_at).toLocaleString('pt-BR')}}</small></article><p v-if="!data.events?.length" class="empty">Nenhum evento público programado.</p></div></section><section id="noticias" class="section"><div class="section-title"><h2>Comunicados</h2></div><article class="notice panel" v-for="n in data.notices" :key="n.id"><h3>{{n.title}}</h3><p>{{n.body||n.message}}</p><small>{{n.published_at||n.created_at}}</small></article><p v-if="!data.notices?.length" class="empty">Nenhum comunicado público.</p></section></main><footer>{{school}} · Portal institucional</footer></div></template>
